"""把日文文字調整成能以中文字碼頁（Big5／GBK）寫回遊戲的形式。

**為什麼未翻譯的文字也需要處理**：一旦把 ``Game.dat`` 的語言標記設成中文，引擎就
會用 Big5 解讀所有文字。Big5 其實收錄了平假名、片假名與大量漢字，所以多數日文原文
**可以原樣轉碼**、在遊戲裡顯示成正常的日文；但只要有一個字不在 Big5 裡，整段就會
變成亂碼方框。連「……。」這種純符號的台詞都會壞掉。

因此導入時對未翻譯的字串也要做一次轉碼，而不是把原本的 CP932 位元組留在那裡。

處理順序：

1. **半形片假名 → 全形**（``ｽﾃｰﾀｽ`` → ``ステータス``）。用 NFKC 但只作用在半形
   片假名上，避免順手把全形數字、全形英文也一起換掉。
2. **符號替換**：Big5 沒有的日文符號換成語意最接近的（``ー`` → ``～``）。
3. **日文新字體 → 正體字**（``撃`` → ``擊``）。Big5 只收正體，日本戰後簡化過的字形
   多半不在裡面。opencc 的簡繁字典不認得這些字形，所以這張表是另外建的。

表中每一組對應都在載入時檢查過目標字確實能以 cp950 編碼（見 ``_selftest``）。
"""

from __future__ import annotations

import unicodedata

__all__ = ["normalise", "unencodable_chars", "SYMBOL_MAP", "JP_TO_TRAD"]

# Big5 沒有的日文符號 → 語意最接近的 Big5 字元
SYMBOL_MAP = {
    "ー": "～",   # ー 長音記號
    "・": "‧",   # ・ 中黑點
    "♪": "～",   # ♪ 音符
    "〜": "～",   # 〜 波浪號
    "［": "〔",   # ［
    "］": "〕",   # ］
    # 模型愛用、但不在 Big5 的口語字（人工確認語意等價）
    "嘞": "啦",   # 嘞 → 啦
    "吡": "嗶",   # 吡 → 嗶
    "咔": "喀",   # 咔 → 喀
}

# 日文新字體 → 正體字。日本戰後簡化的字形不在 Big5 裡，換成對應的正體字後
# 既能編碼、字義也相同。
JP_TO_TRAD = {
    "撃": "擊", "気": "氣", "戦": "戰", "発": "發", "険": "險", "済": "濟",
    "絶": "絕", "闘": "鬥", "増": "增", "変": "變", "実": "實", "剣": "劍",
    "効": "效", "値": "值", "頼": "賴", "毎": "每", "験": "驗", "対": "對",
    "覚": "覺", "応": "應", "広": "廣", "帰": "歸", "楽": "樂", "薬": "藥",
    "処": "處", "択": "擇", "戻": "戾", "悪": "惡", "挿": "插", "顔": "顏",
    "髪": "髮", "乗": "乘", "獣": "獸", "続": "續", "満": "滿", "転": "轉",
    "歩": "步", "読": "讀", "収": "收", "弾": "彈", "軽": "輕", "経": "經",
    "抜": "拔", "鉄": "鐵", "渇": "渴", "売": "賣", "錬": "鍊", "悩": "惱",
    "黒": "黑", "頬": "頰", "沢": "澤", "緑": "綠", "団": "團", "様": "樣",
    "単": "單", "倹": "儉", "両": "兩", "営": "營", "砕": "碎", "説": "說",
    "汚": "污", "繋": "繫", "窓": "窗", "駄": "馱", "円": "圓", "辺": "邊",
    "帯": "帶", "剤": "劑", "払": "拂", "隠": "隱", "遅": "遲", "囲": "圍",
    "駆": "驅", "訳": "譯", "労": "勞", "雑": "雜", "戯": "戲", "揺": "搖",
    "縦": "縱", "焼": "燒", "検": "檢", "倶": "俱", "継": "繼", "脳": "腦",
    "銭": "錢", "歴": "歷", "壊": "壞", "鋭": "銳", "産": "產", "霊": "靈",
    "鹸": "鹼", "拡": "擴", "巻": "卷", "縁": "緣", "恵": "惠", "栄": "榮",
    "蔵": "藏", "塩": "鹽", "掻": "搔", "関": "關", "齢": "齡", "専": "專",
    "痩": "瘦", "畳": "疊", "査": "查", "厳": "嚴", "捜": "搜", "録": "錄",
    "勧": "勸", "犠": "犧", "郷": "鄉", "懐": "懷", "晩": "晚", "穏": "穩",
    "観": "觀", "騒": "騷", "疎": "疏", "隣": "鄰", "氷": "冰", "稲": "稻",
    "竜": "龍", "穂": "穗", "総": "總", "姉": "姊", "菓": "果", "笹": "竹",
    # 以下這些新字體剛好與中文簡化字同形，對應關係取自 opencc 的簡→繁字典，
    # 唯獨「叶」例外：opencc 會把它視為「葉」的簡體，但日文的「叶う」是「實現」，
    # 語意不同，因此人工改成「願」。
    "会": "會", "寝": "寢", "残": "殘", "数": "數", "来": "來", "着": "著",
    "脱": "脫", "当": "當", "状": "狀", "装": "裝", "画": "畫", "学": "學",
    "内": "內", "献": "獻", "奥": "奧", "静": "靜", "点": "點", "断": "斷",
    "横": "橫", "礼": "禮", "挟": "挾", "猫": "貓", "宝": "寶", "乱": "亂",
    "号": "號", "区": "區", "温": "溫", "狭": "狹", "刹": "剎", "叶": "願",
    "潜": "潛", "励": "勵", "湿": "溼", "参": "參", "医": "醫", "届": "屆",
    "国": "國", "盗": "盜", "浅": "淺", "声": "聲", "属": "屬", "誉": "譽",
    "嘘": "噓", "践": "踐", "昼": "晝", "称": "稱", "掴": "摑", "携": "攜",
    "麦": "麥", "却": "卻", "黄": "黃", "尽": "盡", "税": "稅", "恋": "戀",
    "将": "將",
    # 以下是日本自造字（国字），中文沒有對應字形，取字義最接近的常用字。
    # 只作用在「不翻譯就會變亂碼」的文字上，是為了可讀性而非正確翻譯。
    "込": "入",   # 込む → 入
    "匂": "香",   # 匂い（氣味）
    "畑": "田",   # 旱田
    "働": "動",   # 働く（工作）
    "凪": "靜",   # 風平浪靜
}


def _is_halfwidth_kana(ch: str) -> bool:
    return "｡" <= ch <= "ﾟ"


def _fold_halfwidth_kana(text: str) -> str:
    """只把半形片假名（含濁點）折成全形，其餘字元原樣保留。"""
    if not any(_is_halfwidth_kana(ch) for ch in text):
        return text
    out: list[str] = []
    run: list[str] = []
    for ch in text:
        if _is_halfwidth_kana(ch):
            run.append(ch)
            continue
        if run:
            out.append(unicodedata.normalize("NFKC", "".join(run)))
            run = []
        out.append(ch)
    if run:
        out.append(unicodedata.normalize("NFKC", "".join(run)))
    return "".join(out)


def normalise(text: str) -> str:
    """把 ``text`` 調整成盡可能能以 Big5 編碼的形式。"""
    text = _fold_halfwidth_kana(text)
    if any(ch in SYMBOL_MAP for ch in text):
        text = "".join(SYMBOL_MAP.get(ch, ch) for ch in text)
    if any(ch in JP_TO_TRAD for ch in text):
        text = "".join(JP_TO_TRAD.get(ch, ch) for ch in text)
    return text


def unencodable_chars(text: str, encoding: str) -> list[str]:
    """回傳 ``text`` 裡無法以 ``encoding`` 編碼的字元。"""
    bad = []
    for ch in text:
        try:
            ch.encode(encoding)
        except UnicodeEncodeError:
            bad.append(ch)
    return bad


def _selftest() -> None:
    """所有對應目標都必須能以 cp950 編碼，否則這張表就是錯的。"""
    broken = []
    for table in (SYMBOL_MAP, JP_TO_TRAD):
        for src, dst in table.items():
            try:
                dst.encode("cp950")
            except UnicodeEncodeError:
                broken.append((src, dst))
    if broken:
        raise AssertionError(f"對應目標無法以 cp950 編碼: {broken}")


_selftest()
